import { useState } from "react";
import Navbar from "../components/Navbar.js";

const styles = {
  hero: {
    height: "90vh",
    background: "linear-gradient(to right, #1e3a8a, #2563eb)",
    color: "white",
    display: "flex",
    flexDirection: "column",
    justifyContent: "center",
    alignItems: "center",
    textAlign: "center",
    padding: "20px",
  },
  title: {
    fontSize: "42px",
    fontWeight: "bold",
  },
  subtitle: {
    marginTop: "10px",
    marginBottom: "30px",
    fontSize: "18px",
  },
  searchBox: {
    display: "flex",
    gap: "10px",
    background: "white",
    padding: "15px",
    borderRadius: "10px",
    alignItems: "center",
    flexWrap: "wrap",
  },
  input: {
    padding: "10px",
    borderRadius: "6px",
    border: "1px solid #ccc",
    minWidth: "150px",
  },
  swap: {
    padding: "10px",
    fontSize: "18px",
    cursor: "pointer",
    border: "none",
    background: "#e5e7eb",
    borderRadius: "6px",
  },
  searchBtn: {
    background: "#1e40af",
    color: "white",
    padding: "10px 15px",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
  },
};

const Home = () => {
  const [source, setSource] = useState("");
  const [destination, setDestination] = useState("");
  const [date, setDate] = useState("");

  const handleSwap = () => {
    setSource(destination);
    setDestination(source);
  };

  const handleSearch = () => {
    console.log({ source, destination, date });

    // later connect to route page
    // navigate(`/routes?source=${source}&destination=${destination}&date=${date}`);
  };

  return (
    <div>
      <Navbar/>

      {/* HERO SECTION */}
      <div style={styles.hero}>
        <h1 style={styles.title}>Travel Smart with IBTS 🚌</h1>
        <p style={styles.subtitle}>
          Book government buses easily. Track live. Travel smarter.
        </p>

        {/* SEARCH BOX */}
        <div style={styles.searchBox}>
          <input
            type="text"
            placeholder="From (e.g. Lucknow)"
            value={source}
            onChange={(e) => setSource(e.target.value)}
            style={styles.input}
          />

          <button onClick={handleSwap} style={styles.swap}>
            ⇄
          </button>

          <input
            type="text"
            placeholder="To (e.g. Kanpur)"
            value={destination}
            onChange={(e) => setDestination(e.target.value)}
            style={styles.input}
          />

          <input
            type="date"
            value={date}
            onChange={(e) => setDate(e.target.value)}
            style={styles.input}
          />

          <button onClick={handleSearch} style={styles.searchBtn}>
            Search Buses
          </button>
        </div>
      </div>
    </div>
  );
};

export default Home;
